#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MeterPerSecondSquared),
        Acceleration::from_meters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MeterPerSecondSquared),
        Acceleration::from_base(v).as_meters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::NanometerPerSecondSquared),
        Acceleration::from_nanometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::NanometerPerSecondSquared),
        Acceleration::from_base(v).as_nanometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MicrometerPerSecondSquared),
        Acceleration::from_micrometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MicrometerPerSecondSquared),
        Acceleration::from_base(v).as_micrometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MillimeterPerSecondSquared),
        Acceleration::from_millimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MillimeterPerSecondSquared),
        Acceleration::from_base(v).as_millimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::CentimeterPerSecondSquared),
        Acceleration::from_centimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::CentimeterPerSecondSquared),
        Acceleration::from_base(v).as_centimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::DecimeterPerSecondSquared),
        Acceleration::from_decimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::DecimeterPerSecondSquared),
        Acceleration::from_base(v).as_decimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KilometerPerSecondSquared),
        Acceleration::from_kilometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KilometerPerSecondSquared),
        Acceleration::from_base(v).as_kilometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::InchPerSecondSquared),
        Acceleration::from_inches_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::InchPerSecondSquared),
        Acceleration::from_base(v).as_inches_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::FootPerSecondSquared),
        Acceleration::from_feet_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::FootPerSecondSquared),
        Acceleration::from_base(v).as_feet_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerSecond),
        Acceleration::from_knots_per_second(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerSecond),
        Acceleration::from_base(v).as_knots_per_second()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerMinute),
        Acceleration::from_knots_per_minute(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerMinute),
        Acceleration::from_base(v).as_knots_per_minute()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerHour),
        Acceleration::from_knots_per_hour(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerHour),
        Acceleration::from_base(v).as_knots_per_hour()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::StandardGravity),
        Acceleration::from_standard_gravity(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::StandardGravity),
        Acceleration::from_base(v).as_standard_gravity()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MillistandardGravity),
        Acceleration::from_millistandard_gravity(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MillistandardGravity),
        Acceleration::from_base(v).as_millistandard_gravity()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::MeterPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "m/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::MeterPerSecondSquared
        ))
    );
    assert_eq!(
        "nm/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::NanometerPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "nm/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::NanometerPerSecondSquared
        ))
    );
    assert_eq!(
        "µm/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::MicrometerPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "µm/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::MicrometerPerSecondSquared
        ))
    );
    assert_eq!(
        "mm/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::MillimeterPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "mm/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::MillimeterPerSecondSquared
        ))
    );
    assert_eq!(
        "cm/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::CentimeterPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "cm/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::CentimeterPerSecondSquared
        ))
    );
    assert_eq!(
        "dm/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::DecimeterPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "dm/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::DecimeterPerSecondSquared
        ))
    );
    assert_eq!(
        "km/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::KilometerPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "km/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::KilometerPerSecondSquared
        ))
    );
    assert_eq!(
        "in/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::InchPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "in/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::InchPerSecondSquared
        ))
    );
    assert_eq!(
        "ft/s²".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::FootPerSecondSquared)
    );
    assert_eq!(
        format!("2.5 {}", "ft/s²").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::FootPerSecondSquared
        ))
    );
    assert_eq!(
        "kn/s".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::KnotPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kn/s").parse::<Acceleration>(),
        Ok(Acceleration::new(2.5, AccelerationUnit::KnotPerSecond))
    );
    assert_eq!(
        "kn/min".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::KnotPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "kn/min").parse::<Acceleration>(),
        Ok(Acceleration::new(2.5, AccelerationUnit::KnotPerMinute))
    );
    assert_eq!(
        "kn/h".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::KnotPerHour)
    );
    assert_eq!(
        format!("2.5 {}", "kn/h").parse::<Acceleration>(),
        Ok(Acceleration::new(2.5, AccelerationUnit::KnotPerHour))
    );
    assert_eq!(
        "g".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::StandardGravity)
    );
    assert_eq!(
        format!("2.5 {}", "g").parse::<Acceleration>(),
        Ok(Acceleration::new(2.5, AccelerationUnit::StandardGravity))
    );
    assert_eq!(
        "mg".parse::<AccelerationUnit>(),
        Ok(AccelerationUnit::MillistandardGravity)
    );
    assert_eq!(
        format!("2.5 {}", "mg").parse::<Acceleration>(),
        Ok(Acceleration::new(
            2.5,
            AccelerationUnit::MillistandardGravity
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Acceleration>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Acceleration::from_base(6.0);
    let b = Acceleration::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Acceleration::<i64>::from_base(7);
    let b = Acceleration::<i64>::from_base(2);
    assert_eq!(a + b, Acceleration::from_base(9));
    assert_eq!(a % b, Acceleration::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<Acceleration<i64>>(),
        Acceleration::from_base(9)
    );
}
